import importlib.metadata as m,json,platform,sys
expected=json.loads(sys.argv[1]); actual={k:m.version(k) for k in expected}
print(json.dumps({'python':sys.version,'platform':platform.platform(),'optimize':sys.flags.optimize,'expected':expected,'actual':actual},sort_keys=True))
if sys.flags.optimize != 0: raise RuntimeError('Verification requires Python assertions enabled')
if actual != expected: raise RuntimeError('Installed package versions differ from the locks')
